def period(row):
    """The smallest p such that row repeats itself every p cells: len(row) if none is smaller."""
    n=len(row)
    return next(q for q in range(1,n+1) if all(row[j]==row[j-q] for j in range(q,n)))

def fill_staircase(grid):
    """Fill zero holes in a diagonal staircase: row 0 gives the cyclic sequence S of
    period p (read from its zero-free prefix); cell (i,j) gets S[(j + (i > j)) % p]."""
    r0=grid[0]; n=len(r0)
    m=next(i for i,v in enumerate(r0) if v==0) if 0 in r0 else n
    p=period(r0[:m]); S=r0[:p]
    return [[S[(j+(i>j))%p] for j in range(n)] for i,row in enumerate(grid)]
